<script setup>
import {reactive,ref,onMounted} from 'vue'
import SrmModal from '../srm-ui/SrmModal.vue'
import smCrypto from '../utils/smCrypto'
const categories=ref([])
const emit=defineEmits(['close']),form=reactive({invitation:'',name:'',category:'MACHINING',creditCode:'',address:'',contactName:'',phone:'',email:'',account:'',password:'',validCode:'',validCodeReqNo:''}),image=ref(''),error=ref(''),success=ref(''),busy=ref(false)
async function refresh(){const r=await fetch('/api/auth/c/getPicCaptcha').then(r=>r.json());if(r.code!==200)throw new Error(r.msg);image.value=r.data.validCodeBase64;form.validCodeReqNo=r.data.validCodeReqNo;form.validCode=''}
onMounted(async()=>{try{await refresh();const r=await fetch('/api/srm/public/categories').then(r=>r.json());if(r.code!==200)throw new Error(r.msg);categories.value=r.data;form.category=r.data[0]?.code||''}catch(e){error.value=e.message}})
async function submit(){busy.value=true;error.value='';try{const payload={invitation:form.invitation,supplier:{name:form.name,category:form.category,creditCode:form.creditCode,address:form.address},contact:{name:form.contactName,phone:form.phone,email:form.email,roles:['ADMIN'],enabled:true,rowVersion:0},account:{account:form.account,passwordCipher:smCrypto.doSm2Encrypt(form.password)},validCode:form.validCode,validCodeReqNo:form.validCodeReqNo};const r=await fetch('/api/srm/public/register',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}).then(r=>r.json());if(r.code!==200)throw new Error(r.msg);form.password='';success.value='注册成功。请选择供应商门户登录，补齐资质后提交准入。'}catch(e){error.value=e.message;await refresh()}finally{busy.value=false}}
</script>
<template><SrmModal title="供应商注册" @close="emit('close')"><p v-if="success" class="info-note" role="status">{{success}}</p><form v-else @submit.prevent="submit"><label>注册邀请码<input aria-label="注册邀请码" v-model="form.invitation" required minlength="43" maxlength="43" /></label><label>供应商名称<input aria-label="注册供应商名称" v-model="form.name" required maxlength="128" /></label><label>物料品类<select aria-label="注册物料品类" v-model="form.category"><option v-for="c in categories" :key="c.code" :value="c.code">{{c.name}}</option></select></label><label>统一社会信用代码<input aria-label="注册信用代码" v-model="form.creditCode" required minlength="18" maxlength="18" /></label><label>注册地址<input v-model="form.address" maxlength="255" /></label><label>管理员姓名<input aria-label="注册联系人" v-model="form.contactName" required maxlength="32" /></label><label>手机号<input aria-label="注册手机号" v-model="form.phone" required pattern="1[3-9][0-9]{9}" /></label><label>邮箱<input v-model="form.email" type="email" maxlength="64" /></label><label>门户账号<input aria-label="注册账号" v-model="form.account" required pattern="[A-Za-z0-9_.-]{4,64}" autocomplete="username" /></label><label>登录密码<input aria-label="注册密码" v-model="form.password" type="password" required minlength="12" maxlength="20" autocomplete="new-password" /></label><label>验证码<div class="captcha-row"><input aria-label="注册验证码" v-model="form.validCode" required /><button type="button" @click="refresh"><img :src="image" alt="点击刷新验证码" /></button></div></label><p class="info-note">邀请码决定档案归属组织。注册仅建立潜在档案；请补齐有效资质后提交准入。</p><p v-if="error" class="form-error" role="alert">{{error}}</p><div class="modal-actions"><button class="btn primary" :disabled="busy">提交注册</button></div></form></SrmModal></template>
